window.VD=window.VD||{};window.VD["seat-cupra/toledo-nh"]={"toledo-nh-activate-comfort-turn-signals":"<p><strong>Function:</strong> Activates the convenience turn signals.  </p>\n<p><em>(By default, the number of flashes is 3. You can change this value to any number between 1 and 5.) </em>)  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong><br/><br/><strong>4 – </strong>Click on<strong> “Coding – 07” </strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><em>Byte<strong> 12: </strong></em><br/><em>Bit <strong>5</strong>: Check <strong>“Comfort Turn Signals active</strong> ”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte12-011f47aa.webp\"/></figure>","toledo-nh-activate-coming-home-leaving-home":"<p><strong>Purpose: </strong> To activate Coming-Home / Leaving-Home.  </p>\n<p>(To work properly, the vehicle must be equipped with a light sensor. Headlight switch must be in “Auto” position.   <br/>Without the light sensor, it will be necessary to make a headlight call to activate the coming-home).  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p>Byte <strong>10 </strong>: <br/>Bit <strong>1</strong>: Check “Leaving-Home (LH) active”<br/>Bit <strong>2</strong>: Check “Coming-Home (CH) active”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw-polo-6r-cominghome-b8af74dc.webp\"/></figure>","toledo-nh-activate-daytime-running-lights-drl":"<p><strong>Purpose:</strong> to activate the daytime running lights (DRL).  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>23</strong>: </em><br/><em>Bit <strong>6 : </strong> Check Function “Daytime Running Light (DRL)” active</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte23-e94f1178.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>12 </strong>: </em><br/><em>Bit <strong>1</strong>: Tick “Daytime Running Light (DRL) adjustable (Manually AND/OR instrument Cluster)”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte12-2c0d5984.webp\"/></figure>","toledo-nh-activate-driving-school-mode":"<p><strong>Purpose:</strong> Adds a “Driving School” mode view to the RCD 210 / RCD 310 or the Easy Connect MIB2, which displays turn signals, speed, etc. (Also ideal for accompanied driving) <br/><br/><br/><strong>Warning!! There are 3 coding lines to enter here.</strong> <br/><br/><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic port.<br/><br/><strong>2</strong> – Turn on the ignition, then launch the VCDS program.</p>\n<hr/>\n<h4>RCD 210 / RCD 310</h4>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>56 – Radio</strong>.”<br/><br/><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Channel 2</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu toward the bottom<br/>of the page.<br/>From this menu, select “<strong>1</strong>” and then confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/golf6_golf_vi_fahrschulfunktion-5b883ac1.webp\"/></figure>\n<hr/>\n<h4>MIB2: </h4>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Vehicule function list CAN-Driving_school</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Vehicule menu operation-menu_display_driving_school</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/><br/><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Vehicule menu operation-menu_display_driving_school_over_threshold_high</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_6384-e21a59b4.webp\"/></figure>","toledo-nh-activate-hidden-menu":"<p><strong>Purpose:</strong> Activates the green hidden menu (green menu, hidden menu, testmode, engineer mode) on MIB2.</p>\n<p>/!\\ Caution: Making certain changes in the hidden menu may cause MIB2 to freeze or no longer start /!\\<br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“S12345</strong>“.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Developer mode</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, choose the value<strong>“activated</strong>“.</p>\n<p><em>Restart MIB2, keep MENU button pressed until testmode menu appears</em><br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/developermode-bfa51f40.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/developermode2-1024x576-7a0c833c.webp\"/></figure>","toledo-nh-activate-interior-lighting-on-key-removal":"<p><strong>Purpose: </strong>to activate the interior lighting when the key is removed from the neiman.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p>Byte <strong>12</strong>:<br/>Bit<strong> 2</strong>: check “Interior Light after ignition Key removal active”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte12-2c0d5984.webp\"/></figure>","toledo-nh-activate-off-road-mode":"<p><strong>Purpose:</strong> to add Offroad mode to the Easy Connect MIB V2 screen with navigation.  <br/><br/><br/><strong>Watch out! There are 3 lines of coding to do here. </strong> <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_List_BAP_Gen2-compass_0x15</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_Adaptations_Gen2-menu_display_Compass</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/><br/><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_Adaptations_Gen2-menu_display_Compass_over-threshold_high</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/offroad-menu-seat-leon-vcds-obdeleven-coding-40129c7d.webp\"/></figure>\n<p>Additional line if OFF Road not activated :</p>\n<p>Car_Function_Adaptations_Gen2</p>\n<p>menu_display_compass: change the value to “activated” [Standard: “Not activated”]<br/>menu_display_compass_over_therhold_high: change the value to “activated” [Standard: “Not activated”]<br/>menu_display_angle_of_slope: change the value to “activated” [Standard: “Not activated”]<br/>menu_display_angle_of_slope_over_threshold_high: change the value to “activated” [Standard: “Not activated”]</p>\n<p>Car_Function_List_Bap_Gen2</p>\n<p>compass_0x15: change the value to “activated” [Standard: “Not activated”]<br/>compass_0x15_msg_bus: change the value to “Comfort data bus”<br/>angle_of_slope_0x24: change the value to “activated” [Standard: “Not activated”]<br/>angle_of_slope_0x24_msg_bus: change the value on “Comfort data bus”</p>","toledo-nh-activate-rain-sensor":"<p><strong>Purpose</strong>: to activate the rain sensor.  </p>\n<p><strong>Procedure:</strong> <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/>3 – Click on ” <strong>Select</strong> “, then click on ” <strong>09 – Cent. Elect.</strong>” . Switch on the ignition and run the VCDS program. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Click on “Long Coding Helper” :</p>\n<p><strong>6</strong> – In the window that appears, select,</p>\n<p><em>Byte <strong>14</strong>: </em> <br/><em>Bit <strong>1</strong>: Check “Rain Sensor Function active”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte14-cd640f80.webp\"/></figure>\n<p><strong>Line 2: </strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Select the “RLS” module and click on “Long Coding Helper”:</p>\n<p><em><em>Byte <strong>4</strong>: </em></em><br/><em><em>Bit <strong>5</strong>: Uncheck “Rain Sensor inactive”.</em></em></p>","toledo-nh-activate-usb-port-for-iphone-carplay-retrofit":"<p><strong>Purpose:</strong> Enables the USB port for iPhone CarPlay accounting (after Full Link activation and USB and/or USB cable change) for MIB2 (Retrofit). </p>\n<p>For firmware references: <br/>MST2_EU_SE_ZR_P02XXT (before 2016)</p>\n<p>Modify the MIB2 coding and adaptation to recognize the new USB port (USB connector ref 5Q0 035 726 E) for both CarPlay and USB multimedia playback. A coding pin on the connector needs to be modified.  </p>\n<p><a href=\"#/t/app-connect-carplay-activation\"><strong>–&gt; Full Link CarPlay and Android Auto Activation</strong></a><br/><a href=\"https://www.vag-custom.fr/produit/prise-usb-aux-vw-golf-7-carplay-media-mib2-5q0-035-726-e/\" rel=\"noopener\" target=\"_blank\"><strong>–&gt; VW Golf 7 USB/AUX Port for CarPlay Media MIB2 5Q0 035 726 E on VAG Custom</strong></a><br/><strong><a href=\"#/seat-cupra/leon-5f/leon-5f-add-carplay-android-auto-after-activating-full-link-mib2-2xxt\">–&gt; Adding CarPlay / Android Auto after activating Full Link MIB2 2xxT</a></strong><br/><strong><a href=\"#/seat-cupra/toledo-nh/toledo-nh-deactivate-mirrorlink\">–&gt; Disable MirrorLink</a></strong><br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Codage- 07</strong>” then click on<strong>“Assistant Codage Long</strong>”.<br/><br/><strong>5 </strong>– Select byte<strong>“19</strong>“<br/>Then check Bit<strong>“6-7</strong>” (C0 USB Configuration: USB and iPhone Functionality)<br/><br/><strong>Line 2 <strong>(optional)</strong></strong> <strong>:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose “<strong><strong>Interface for external media activation – connection 1</strong></strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, choose the value “<strong><strong>activated</strong></strong>“<br/><br/></p>\n<figure>\n<blockquote><a href=\"https://www.vag-custom.fr/produit/activation-full-link-pour-seat/\" rel=\"noopener\" target=\"_blank\">Activation FULL LINK pour Seat</a></blockquote>\n</figure>\n<figure>\n<blockquote><a href=\"https://www.vag-custom.fr/produit/prise-usb-aux-vw-golf-7-carplay-media-mib2-5q0-035-726-e/\" rel=\"noopener\" target=\"_blank\">Prise USB / AUX VW Golf 7 CarPlay Media MIB2 5Q0 035 726 E</a></blockquote>\n</figure>","toledo-nh-activate-wiper-change-mode":"<p><strong>Purpose</strong>: activates changeover mode for front wipers.  </p>\n<p><strong>Procedure:</strong> <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/>3 – Click on ” <strong>Select</strong> “, then click on ” <strong>09 – Cent. Elect.</strong>” . Switch on the ignition and run the VCDS program. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Click on “Long Coding Helper” :</p>\n<p><strong>6</strong> – In the window that appears, select,</p>\n<p><em>Byte <strong>14</strong>: </em><br/><em>Bit<strong> 2</strong>: Check “Service Position for Front Wiper active”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte14-cd640f80.webp\"/></figure>\n<p><strong>Line 2: </strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>” .</p>\n<p><strong>5</strong> – Select <strong>Channel 23</strong>: <em>Set value to 1.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Adaptation_channel231-91e9521d.webp\"/></figure>","toledo-nh-add-carplay-android-auto-after-activating-full-link-mib2-2xxt":"<p><strong>Purpose:</strong> Allows you to add Apple CarPlay and Android Auto to Full Link after it has been enabled on MIB2 systems with 2xxT part numbers, when only MirrorLink appears in the Full Link menu. </p>\n<p>For the firmware reference: <br/>MST2_EU_SE_ZR_P02XXT</p>\n<p><strong><a href=\"#/t/app-connect-carplay-activation\">–&gt; Full Link CarPlay and Android Auto Activation</a></strong><br/><a href=\"#/seat-cupra/toledo-nh/toledo-nh-deactivate-mirrorlink\"><strong>–&gt; Disable MirrorLink</strong></a><br/><strong><a href=\"#/seat-cupra/toledo-nh/toledo-nh-activate-usb-port-for-iphone-carplay-retrofit\">–&gt; Enable the USB port for iPhone CarPlay (retrofit)</a></strong><br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>“.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Vehicle Configuration – <strong>Apple_DIO</strong></strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu located toward the bottom<br/>.<br/>From this menu, select “<strong>Enabled</strong>” and then confirm.</p>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>“.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Vehicle Configuration – Google_GAL</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu further down<br/>.<br/>From this menu, select “<strong><strong>Enabled</strong></strong>” and then confirm.</p>\n<figure>\n<blockquote><a href=\"https://www.vag-custom.fr/produit/activation-full-link-pour-seat/\" rel=\"noopener\" target=\"_blank\">Activation FULL LINK pour Seat</a></blockquote>\n</figure>","toledo-nh-adjust-light-sensor-sensitivity":"<p><strong>Purpose: </strong>Adjusts the sensitivity of the light sensor.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “2 EPIRBs” module from the drop-down list and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>0</strong>:  </em><br/><em>Bits <strong>3–4</strong>: Select from the drop-down list<br/>– 00 Normal light activation threshold<br/>– 08 Earlier light activation threshold (+20%)<br/>– 10 Light Activation Threshold earlier (+40%)<br/>– 08 Light Activation Threshold earlier (+60%)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Calc09-RLS-140kmhBit0-Octet0-4f74e4e9.webp\"/></figure>","toledo-nh-automatic-closing-of-windows-and-roof-in-case-of-rain":"<p><strong>Purpose</strong>: Automatically closes windows and sunroof when it rains.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>09 – Cent. Elect.</strong>” . Switch on the ignition and run the VCDS program. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “<strong>Coding 07</strong>”.</p>\n<p><strong>5</strong> – Click on “Long Coding Helper” :</p>\n<p><strong>6</strong> – In the window that appears, select:</p>\n<p><em>Byte <strong>4</strong>: </em><br/><em>Bit <strong>6: </strong> Check “Rain closing active”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/4A6D5E39-CE5A-476F-995D-444CD637E3AD-af64c8a6.webp\"/></figure>\n<p><strong>Line 2 </strong>:</p>\n<p><strong>3</strong> – Click on “<strong>Select</strong>” then click on “<strong>09 – Cent. Elect.</strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “RLS” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>4</strong>: </em><br/><em>Bit <strong>2</strong>: Check “Rain closing active”.</em></p>","toledo-nh-automatic-door-locking-after-30s":"<p><strong>Purpose: </strong>to set automatic door unlocking when the vehicle has been unlocked but no doors have been opened for 30 seconds.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>4</strong>: </em><br/><em>Bit <strong>5</strong>: Uncheck “Central Locking Re-locking (after 30 seconds) active”.</em><em><br/></em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte4-6c468b48.webp\"/></figure>","toledo-nh-automatic-door-locks":"<p><strong>Purpose: </strong>to set automatic door locking from 15km/h.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>4</strong>: Check “Auto-Lock (Automatic Locking above 15 km/h)”.</em><em><br/></em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte0-87553eca.webp\"/></figure>","toledo-nh-automatic-door-unlocking":"<p><strong>Purpose: </strong>to configure automatic door unlocking when the ignition key is removed.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>3</strong>: Check “Auto-Unlock (Unlocking when Removing the Ignition Key)”.</em><em><br/></em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte0-87553eca.webp\"/></figure>","toledo-nh-automatic-headlight-activation-from-140-km-h":"<p><strong>Purpose: </strong>to automatically switch on the lights when the vehicle is travelling at over 140 km/h. </p>\n<p>(The lights will automatically go out if the vehicle is travelling at less than 60 km/h) </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “2 EPIRBs” module from the drop-down list and click on “Long Coding Helper”:</p>\n<p>Byte <strong>0</strong>: <br/>Bit <strong>0</strong>: Check “Highway Light Function active above (140kph/90mph)”. </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Calc09-RLS-140kmhBit0-Octet0-4f74e4e9.webp\"/></figure>","toledo-nh-change-number-of-flashes-comfort-flashers":"<p><strong>Purpose:</strong> Allows you to change the number of flashes after activating the comfort turn signals.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong><br/><br/><strong>4 – </strong>Click on<strong> “Adaptation – 10” </strong></p>\n<p>5 – Select<strong> Channel 43</strong> (Lights: Comfort Turn Signals (Cycles) from the drop-down list)</p>\n<p><em>Select a value between 1 and 5</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Adaptation_channel43-3a96f44b.webp\"/></figure>","toledo-nh-change-odb-language":"<p><strong>Purpose:</strong> Select the language of your on-board computer.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Language Version</strong>”.<br/><br/><strong>6</strong> – Select language from second value list  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/886F4702-2DBC-4C30-8716-D4D05CCE1338-da4cd84c.webp\"/></figure>","toledo-nh-coming-leaving-home-with-fog-lamps":"<p><strong>Purpose: </strong>Enables fog lamps to be used for Coming Home and Leaving Home.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p>Byte <strong>13</strong>:<br/>Bit<strong> 6</strong>: Uncheck “Coming-Home (CH) / Leaving-Home (LH) Variant (0 = Fog Lights / 1 = Low Beam)”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte13-092427d2.webp\"/></figure>","toledo-nh-corner-lights":"<p><strong>Purpose:</strong> Allows you to turn on the cornering lights along with the fog lights.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong><br/><br/><strong>4 – </strong>Click on<strong> “Coding – 07” </strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><em><strong>Byte 12: </strong></em><br/><em>Bit <strong>6</strong>: Check <strong>“Turn/Cornering Lights</strong> installed/active”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte12-011f47aa.webp\"/></figure>","toledo-nh-corner-lights-with-turn-signal":"<p><strong>Purpose:</strong> Enables the cornering lights to turn on along with the fog lights when the turn signal is activated.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong><br/><br/><strong>4 – </strong>Click on<strong> “Coding – 07” </strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><em>Byte <strong>21: </strong></em><br/><em>Bit <strong>2</strong>: Check <strong>“Cornering/Turn Lights via Turn Signal active</strong> ”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte21-023ebd48.webp\"/></figure>","toledo-nh-deactivate-am-frequency":"<p><strong>Purpose:</strong> to disable the AM radio frequency on the display (AM radio frequency is rarely used, unlike FM radio frequency).  </p>\n<p><br/><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>”.</p>\n<p><strong>5</strong> – Click on “<strong>Long Coding Helper</strong>” .</p>\n<p><strong>6</strong> – Select Byte <strong>14</strong></p>\n<p>Set bit <strong>1</strong> <strong>“AM_disable</strong></p>\n<figure>\n</figure>","toledo-nh-deactivate-horn-without-ignition":"<p><strong>Purpose:</strong> to deactivate the horn when the ignition is off.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on <strong>“Coding – 07”</strong> then <strong>“Long Coding Helper”.</strong><br/><br/><strong>5</strong> – Select Byte <strong>17</strong>, Bit <strong>3</strong><br/><br/><strong>6</strong> – Check <strong>“Horn with” Terminal 15 OFF “inactive</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/8B27B62E-B23B-4D69-A15C-C56C9A00FC14-c93db85d.webp\"/></figure>","toledo-nh-deactivate-mirrorlink":"<p><strong>Purpose:</strong> Allows you to disable or remove MirrorLink from Full Link on the MIB. The MirrorLink service has not been natively available on Android since June 1, 2020. For a direct connection to Android Auto.   <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>“.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Vehicle configuration-Mirror_link</strong>“.<br/><br/><strong>7</strong> – On the same page, you’ll find a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“Disabled</strong>” and confirm.</p>","toledo-nh-deactivate-windshield-washer-indicator":"<p><strong>Purpose:</strong> to deactivate the windshield washer indicator on the ODB (on-board computer).  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on “<strong>Long Coding Helper</strong>” .</p>\n<p><strong>5</strong> – Select byte <strong>1</strong>:<br/>Then uncheck Bit <strong>2: </strong>“<strong>Washer Fluid warning active/installed</strong>”.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6J0-920-802-J_Module17_Byte1-5e3ec890.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/laveglace-edc83d4f.webp\"/></figure>","toledo-nh-delete-belt-alarm":"<p><strong>Purpose:</strong> To suppress the audible alarm and the warning light on the speedometer when driving without a seatbelt.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on “<strong>Long Coding Helper</strong>” .</p>\n<p><strong>5</strong> – Select byte <strong>1</strong>:<br/>Then uncheck Bit <strong>1: </strong>“<strong>Seatbelt warning active/installed</strong>”.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6J0-920-802-J_Module17_Byte1-5e3ec890.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant_ceinture_de_securite-296648a9.webp\"/></figure>","toledo-nh-delete-odb-error-led-license-plate-light":"<p><strong>Purpose:</strong> Eliminates the error on the ODB when replacing original license plate light bulbs with non-error LEDs.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select</strong>” then click on “<strong>09 – Cent. Elect.</strong>” .<br/><br/><strong>4 </strong>– Click on “<strong> Coding – 07 </strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em><strong>Byte 11 </strong>: </em><br/><em>Bit <strong>7</strong>: Uncheck “</em>Lamp diagnotics for Lisense Plate Light active<em>”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte11-e6e5cf22.webp\"/></figure>","toledo-nh-dimming-leds-with-turn-signals":"<p><strong>Purpose:</strong> Maintains the brightness of the LEDs when the turn signals are on. </p>\n<p><strong>Procedure </strong>: <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p>Bytes<strong> 23</strong>: <br/>Bit<strong> 7</strong>: This is a hidden bit; you must replace the 0 with a 1 directly in “Binary” (the eighth 0 with a 1)</p>","toledo-nh-disable-bluetooth-connection-beep":"<p><strong>Purpose </strong>: Disables the beep when a device successfully connects to the car radio’s Bluetooth.  </p>\n<p><strong>Procedure </strong>: <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“77 – Telephone</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Adaptation 10</strong>”.</p>\n<p><strong>5</strong> – Select “Bluetooth acknowledgement signal” from the value list</p>\n<p><strong>6 </strong>– Select <strong>“Off” </strong>from the second drop-down list</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/7P6-035-730-C_Module77_Adaptation_Bluetooth_acknow-580a5d47.webp\"/></figure>","toledo-nh-disable-parking-assist-beep":"<p><strong>Purpose:</strong> to deactivate the beep when reverse gear is engaged or when parking assistance is activated manually.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “10-Parking<strong>Assistance.”</strong><br/><br/><strong>4 – </strong>Click on<strong> “Adaptation – 10” </strong></p>\n<p><strong>5</strong> – Select <em>“Parking Aid Activation Tone</em> ” from the drop-down list<strong>:</strong></p>\n<p><em>Select <strong>“Off” from </strong>the second drop-down list</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6J0-919-475-B_Module10_Adaptation_Parking_aid_acti-4dbee393.webp\"/></figure>","toledo-nh-disable-rear-wiper-when-reversing":"<p><strong>Purpose:</strong> to deactivate the automatic engagement of the rear wiper when reversing.  </p>\n<p><strong>Procedure:</strong> <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/>3 – Click on ” <strong>Select</strong> “, then click on ” <strong>09 – Cent. Elect.</strong>” . Switch on the ignition and run the VCDS program. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Click on “Long Coding Helper” :</p>\n<p><strong>6</strong> – In the window that appears,</p>\n<p><em>Byte <strong>14 </strong>: </em><br/><em>Bit<strong> 3</strong>: Uncheck “Comfort Funtion for Rear Wiper active”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte14-cd640f80.webp\"/></figure>","toledo-nh-door-lock-unlock-confirmation-beep-horn":"<p><strong>Purpose: </strong>to set confirmation of door locking/unlocking with beep (alarm) or horn.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>5</strong>: </em><br/><em>Bit <strong>1</strong>: Tick “Acoustical Locking Confirmation (Horn) active”.</em><br/><em>Bit <strong>4</strong>: Tick “Acoustical Unlocking Confirmation (Horn) active”. </em><br/><em>Bit <strong>7</strong>: Tick “Anti-Theft-System Activation Acoustical Confirmation (Horn) active”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte5-90daaa01.webp\"/></figure>","toledo-nh-door-lock-unlock-confirmation-turn-signals":"<p><strong>Purpose: </strong>Used to set up confirmation of door locking using the indicators.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>5</strong>: </em><br/><em>Bit <strong>0</strong>: Check “Locking/Unlocking Optical Confirmation (Turn Signal) active”.</em><em><br/></em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte5-90daaa01.webp\"/></figure>","toledo-nh-enable-bluetooth-audio-a2dp":"<p><strong>Purpose </strong>: Enables Bluetooth audio (A2DP).  </p>\n<p>You can listen to music from your A2DP-compatible phone or mp3 player.  </p>\n<p><strong>Procedure </strong>: <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“77 – Telephone</strong>”.</p>\n<p><strong>4</strong> – Click on<strong> “Coding – 07”</strong> then<strong> “Long Coding Helper”.</strong></p>\n<p><strong>5 </strong>– <em>Byte<strong> 4 </strong>: </em><br/><em>Bit <strong>0</strong>: Uncheck <strong>“Multimedia Function (Bluetooth Audio) inactive”.</strong></em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/D836B768-D607-4E70-92E6-06200694DE00-4d4d00be.webp\"/></figure>","toledo-nh-lights-in-flash-mode-during-emergency-braking":"<p><strong>Purpose</strong>: activates the brake/turn signal lights in flash mode during emergency braking.  </p>\n<p><strong>Procedure: </strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket. <br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>12</strong>: </em><br/><em>Bit <strong>3</strong>: Check “Emergency Flashing<em>(Turn Signals) active </em>” (to activate turn signals)</em><br/><em>Bit <strong>4</strong>: Tick “Emergency Brake Flashing (Brake Light) active” (to activate brake lights)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte12-2c0d5984.webp\"/></figure>","toledo-nh-memory-for-heated-seats":"<p><strong>How it works :</strong> When you switch on the heated seat(s), as soon as you remove the key from the ignition the setting is immediately switched off. With this activation, when you switch the ignition back on, the seat will have returned to the level at which you left it.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“08 – Climatronic</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose  </p>\n<p>“<strong>Retention of driver’s seat heater level</strong>” for <strong>Driver’s seat heater memory</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/3AA-907-044-AG_Module08_Adaptation_retention_of_dr-51646659.webp\"/></figure>\n<p>and/or<strong>“Retention of passenger’s seat heater level</strong>” for <strong>Passenger seat heater memory</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/3AA-907-044-AG_Module08_Adaptation_retention_of_pa-61b11e06.webp\"/></figure>\n<p><br/><strong>6</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“active</strong>” and confirm.</p>","toledo-nh-needle-check":"<p><strong>Purpose:</strong> activates needle sweep when the car is started. (Needle Sweep)   <br/></p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>10-Adaptation</strong>” then in the window that appears, click on the drop-down menu to choose a channel and select the “<strong>Staging</strong>” channel, if unavailable select the “<strong>indicator_celebration</strong>” channel:</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/checkg6-9456b738.webp\"/></figure>\n<p><strong>5</strong> – In the “<strong>New value</strong>” box, click on the drop-down menu and select “<strong>active</strong>”. Once this new value has been entered, click on “<strong>Save</strong>”:</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/checkg62-c8918051.webp\"/></figure>","toledo-nh-park-assist-beep-frequency-setting":"<p><strong>Purpose:</strong> Allows you to adjust the frequency of the rear beeps during parking assistance.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “10-Parking<strong>Assistance.”</strong><br/><br/><strong>4 – </strong>Click on<strong> “Adaptation – 10” </strong></p>\n<p><strong>5</strong> – Select <em>“Speaker frequency for rear parking aid</em> ” from the drop-down list<strong>:</strong></p>\n<p><em>Select</em>a frequency from <em>Stage 1</em> (Low) to <em>Stage 9</em> (High) from the second drop-down list</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0_Module10_Adaptation_speaker-frequency_for_rear-a3ec7081.webp\"/></figure>","toledo-nh-programming-a-remote-control":"<p><strong>Purpose:</strong> Allows you to program the remote controls that will be used with the vehicle for central locking and unlocking.  </p>\n<p>⚠️ <strong>WARNING:</strong> This procedure does not allow you to program remote controls with the vehicle’s immobilizer.<br/>If your vehicle is equipped with a <strong>KESSY</strong> remote control <strong>(05 – Access/Ignition Authorization)</strong>, you cannot program a new remote control using this procedure.</p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click <strong>“Select</strong>,” then click “ <strong><strong>“09 – Cent. Elect.”</strong></strong>.”<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 01 ( </strong>“Remote Control Adaptation” from the drop-down list)</p>\n<p>Enter the number of keys to program, then click <strong>Save</strong>.<br/>Next, press the <strong>Unlock</strong> button on each remote control to be programmed for at least 1 second. The flashing lights will confirm the process.<br/>All keys must be programmed in a single session, one after the other.<br/>Programming all keys must not take longer than <strong>15 seconds</strong>.<br/>You can add up to <strong>7 remote controls</strong>. If the <strong>[Test]</strong> and/or <strong>[Save]</strong> buttons are grayed out and unclickable, the module likely has all 7 slots filled; delete the remote controls using the <strong>“Reset Remote Controls”</strong> tutorial.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/programmertelecommande-51bf4068.webp\"/></figure>","toledo-nh-display-of-make-up-quantity-on-odb":"<p><strong>Purpose:</strong> Displays the amount of fuel needed to completely fill your tank on the ODB.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>“.<br/><br/><strong>4</strong> – Click on <strong>“Adaptation – 10” </strong>.<br/><br/><strong>5</strong> – Select <strong>“Volume to be Replenished” </strong>from the value list.</p>\n<p>Select ” <strong>Yes</strong> ” in the second value list.</p>","toledo-nh-resetting-remote-controls":"<p><strong>Purpose:</strong> Resets the settings for all remote controls associated with the vehicle. </p>\n<p><strong>⚠️ WARNING:</strong> After completing this procedure, all remote controls will be deleted and will need to be reprogrammed using the <strong>“Program a Remote Control”</strong> tutorial <strong>.</strong><br/>If your vehicle is equipped with a <strong>KESSY</strong> remote control <strong>(05 – Access/Start Authorization)</strong>, you cannot delete the remote controls using this procedure.</p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click <strong>“Select</strong>,” then click “ <strong><strong><strong>“09 – Cent. Elect.”</strong></strong></strong>.”<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 00</strong></p>\n<p><em>Set the value to <strong>0</strong> and save</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6Q0-959-433-E_Module46_Adaptation_Channel00-caced031.webp\"/></figure>","toledo-nh-retrofit-heated-mirrors":"<p><strong>Function</strong>: Turns on the heated and defrosting side mirrors.  </p>\n<p>The vehicle must be equipped with heated side mirrors. Or, for the installation of heated side mirrors (retrofit)   </p>\n<p><strong>Procedure:</strong> <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/>3 – Click on ” <strong>Select</strong> “, then click on ” <strong>09 – Cent. Elect.</strong>” . Switch on the ignition and run the VCDS program. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Click on “Long Coding Helper” :</p>\n<p><strong>6</strong> – In the window that appears,</p>\n<p><em>Byte <strong>14: </strong></em><br/><em>Bit<strong> 3</strong>: Check “Mirror Heating ON while rear Window Heater ON”<br/>Bit <strong>7</strong>: Check “Heated Outside Mirrors installed”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte15-1c45d71d.webp\"/></figure>","toledo-nh-selective-door-unlocking":"<p><strong>Purpose: Allows </strong>you to configure selective door unlocking. <br/></p>\n<p>When unlocking the vehicle, only the driver’s door is unlocked. To unlock all doors, press the remote control’s unlock button twice.   </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>0</strong>: Check “Selective Central Locking (Single Door Locking) active”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte0-87553eca.webp\"/></figure>","toledo-nh-tear-wiping":"<p><strong>Purpose:</strong> to activate the windshield wipers once more after using the windshield washer, in order to remove any remaining water from the windshield.  </p>\n<p><strong>Procedure:</strong> <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/>3 – Click on ” <strong>Select</strong> “, then click on ” <strong>09 – Cent. Elect.</strong>” . Switch on the ignition and run the VCDS program. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on <strong>“Coding – 07”</strong> then <strong>“Long Coding Helper”.</strong></p>\n<p><strong>5</strong> – Select byte <strong>14</strong>, <br/>Bit <strong>4</strong>, Check <strong>“Tear Wiping Active”</strong>.</p>","toledo-nh-coming-leaving-home-with-headlights":"<p><strong>Purpose: Allows you </strong>to use xenon (or halogen) headlights for the Coming Home and Leaving Home functions.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>13</strong>: </em><br/><em>Bit <strong>6</strong>: Check “Coming-Home (CH) / Leaving-Home (LH) Variant (0 = Fog Lights / 1 = Low Beam)”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte13-092427d2.webp\"/></figure>"};
